/*
 * ring/test/test_ring_data.c - the RING and RINGLOG module data blocks
 * (source-vulx)
 *
 * Generated by: Claude Opus 5.5
 *
 * ring/data.c and ring/ringlog_data.c are #included, so the objects under
 * test are the real blocks with the image's contents:
 *
 *   RING_$WIRED_DATA  map "D E261AC RING_WIRED size = AC"
 *   RING_$CTL         map "D E86400 RING size = 5D0"
 *   RINGLOG_$CTL      map "D E2C32C RINGLOG_ size = 3C"
 *   RINGLOG_$DATA     map "D53 EA3E38 RINGLOG_$DATA size = 11FC"
 *
 * RING_$CTL holds pointers (its offsets are asserted at compile time on the
 * target only); its image contents are checked field by field.  The driver
 * record's procedure variables name the routines, which are stubbed here.
 */

#include <stdint.h>
#include <stdio.h>
#include <string.h>

static int tests_failed = 0;
static int tests_run = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  Running %s... ", #name);                                    \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("done\n");                                                     \
    } while (0)

#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long _e = (long long)(expected);                                 \
        long long _a = (long long)(actual);                                   \
        if (_e != _a) {                                                       \
            printf("FAILED\n    Expected: 0x%llx, Got: 0x%llx at line %d\n",  \
                   (unsigned long long)_e, (unsigned long long)_a, __LINE__); \
            tests_failed++;                                                   \
            return;                                                           \
        }                                                                     \
    } while (0)

