#include "../data.c"
#include "../ringlog_data.c"

#define OFF(block, field) \
    ((size_t)((const uint8_t *)&(field) - (const uint8_t *)&(block)))

TEST(block_addresses_and_sizes)
{
    ASSERT_EQ(0x00E261ACu, MODULE_DATA_ADDR(RING_$WIRED_DATA));
    ASSERT_EQ(0x00E86400u, MODULE_DATA_ADDR(RING_$CTL));
    ASSERT_EQ(0x00E2C32Cu, MODULE_DATA_ADDR(RINGLOG_$CTL));
    ASSERT_EQ(0x00EA3E38u, MODULE_DATA_ADDR(RINGLOG_$DATA));
    ASSERT_EQ(0xAC, sizeof(RING_$WIRED_DATA));
    ASSERT_EQ(0x3C, sizeof(RINGLOG_$CTL));
    ASSERT_EQ(0x11FC, sizeof(RINGLOG_$DATA));
    ASSERT_EQ(0x5D0, RING_$CTL_SIZE);
    /* RING_WIRED ends where RIP_WIRED begins */
    ASSERT_EQ(0x00E26258u, MODULE_DATA_ADDR(RING_$WIRED_DATA) + RING_$WIRED_DATA_SIZE);
}

TEST(wired_offsets_and_stride)
{
    ASSERT_EQ(0x00, OFF(RING_$WIRED_DATA, RING_$WIRED_DATA.swdiag_nodeid));
    ASSERT_EQ(0x08, OFF(RING_$WIRED_DATA, RING_$WIRED_DATA.swdiag_rcvcnt));
    ASSERT_EQ(0x0C, OFF(RING_$WIRED_DATA, RING_$WIRED_DATA.rcv_biphase));
    ASSERT_EQ(0x12, OFF(RING_$WIRED_DATA, RING_$WIRED_DATA.xmit_esb));
    ASSERT_EQ(0x14, OFF(RING_$WIRED_DATA, RING_$WIRED_DATA.paging_overflow));
    ASSERT_EQ(0x16, OFF(RING_$WIRED_DATA, RING_$WIRED_DATA.swdiag));
    ASSERT_EQ(0x34, OFF(RING_$WIRED_DATA, RING_$WIRED_DATA.stats[0]));
    ASSERT_EQ(0x70, OFF(RING_$WIRED_DATA, RING_$WIRED_DATA.stats[1]));
    /* ring_$stats_t is packed: the longwords stay at +0x02 / +0x06 */
    ASSERT_EQ(0x02, OFF(RING_$WIRED_DATA.stats[0], RING_$WIRED_DATA.stats[0].xmit_call));
    ASSERT_EQ(0x1C, OFF(RING_$WIRED_DATA.stats[0], RING_$WIRED_DATA.stats[0].rcvcnt));
}

TEST(wired_initial_contents)
{
    const uint8_t *p = (const uint8_t *)&RING_$WIRED_DATA;
    size_t i;

    /* the words 1 at +0x16, +0x34 and +0x70; zero elsewhere */
    for (i = 0; i < sizeof(RING_$WIRED_DATA); i++) {
        if ((i & ~(size_t)1) == 0x16 || (i & ~(size_t)1) == 0x34 ||
            (i & ~(size_t)1) == 0x70) {
            continue;
        }
        ASSERT_EQ(0, p[i]);
    }
    ASSERT_EQ(1, RING_$WIRED_DATA.swdiag._r00);
    ASSERT_EQ(1, RING_$WIRED_DATA.stats[0]._reserved0);
    ASSERT_EQ(1, RING_$WIRED_DATA.stats[1]._reserved0);
}

TEST(ctl_driver_record)
{
    const net_io_$driver_t *d = &RING_$CTL.driver;

    ASSERT_EQ(2, d->_unknown0);
    ASSERT_EQ(0x400, d->max_data_len);
    ASSERT_EQ(0, d->mtu);
    ASSERT_EQ(3, d->flags);
    ASSERT_EQ((uintptr_t)RING_$SENDP, (uintptr_t)d->sendp);
    ASSERT_EQ((uintptr_t)RING_$GET_STATS, (uintptr_t)d->get_stats);
    ASSERT_EQ((uintptr_t)RING_$GET_STATS, (uintptr_t)d->get_stats2);
    ASSERT_EQ((uintptr_t)RING_$START, (uintptr_t)d->start);
    ASSERT_EQ((uintptr_t)RING_$STOP, (uintptr_t)d->stop);
    ASSERT_EQ(0, (uintptr_t)d->detach);
    ASSERT_EQ((uintptr_t)RING_$PROC2_CLEANUP, (uintptr_t)d->proc2_cleanup);
    ASSERT_EQ((uintptr_t)RING_$IOCTL, (uintptr_t)d->ioctl);
    ASSERT_EQ((uintptr_t)RING_$SVC_OPEN, (uintptr_t)d->svc_open);
    ASSERT_EQ((uintptr_t)RING_$SVC_CLOSE, (uintptr_t)d->svc_close);
    ASSERT_EQ((uintptr_t)RING_$SVC_IOCTL, (uintptr_t)d->svc_ioctl);
    ASSERT_EQ((uintptr_t)RING_$SVC_WRITE, (uintptr_t)d->svc_write);
    ASSERT_EQ((uintptr_t)RING_$SVC_READ, (uintptr_t)d->svc_read);
    ASSERT_EQ((uintptr_t)RING_$OPEN_OS, (uintptr_t)d->open_os);
    ASSERT_EQ((uintptr_t)RING_$CLOSE_OS, (uintptr_t)d->close_os);
    ASSERT_EQ((uintptr_t)RING_$SEND_OS, (uintptr_t)d->send_os);
    ASSERT_EQ(0, d->network_uid.high);
    ASSERT_EQ(0, d->network_uid.low);
}

TEST(ctl_clocks_and_procs)
{
    ASSERT_EQ(0, RING_$CTL.force_start_timeout.high);
    ASSERT_EQ(0, RING_$CTL.force_start_timeout.low);
    ASSERT_EQ(0x0089, RING_$CTL._r570.low);
    ASSERT_EQ(0x0422, RING_$CTL.xmit_timeout1.low);
    ASSERT_EQ(0x02AB, RING_$CTL.xmit_timeout2.low);
    ASSERT_EQ(0x02AB, RING_$CTL._r588.low);
    ASSERT_EQ(0x0177, RING_$CTL.poll_timeout.low);
    ASSERT_EQ(5, RING_$CTL.wait_timeout.high);
    ASSERT_EQ(0x9E22, RING_$CTL.wait_timeout.low);
    ASSERT_EQ((uintptr_t)RING_$RCV0, (uintptr_t)RING_$CTL.rcv_proc[0]);
    ASSERT_EQ((uintptr_t)RING_$RCV1, (uintptr_t)RING_$CTL.rcv_proc[1]);
    ASSERT_EQ(0, RING_$CTL.wire_cnt);
    ASSERT_EQ(0, RING_$CTL.rcv_int_cnt);
}

TEST(unit_table_bias)
{
    ring_unit_t *u = &RING_$CTL.units[0];

    ASSERT_EQ((uintptr_t)&u->channels[0], (uintptr_t)&RING_UNIT_CHANNEL(u, 1));
    ASSERT_EQ((uintptr_t)&u->channels[RING_MAX_CHANNELS - 1],
              (uintptr_t)&RING_UNIT_CHANNEL(u, RING_MAX_CHANNELS));
    ASSERT_EQ((uintptr_t)&u->pkt_types[0], (uintptr_t)&RING_UNIT_PKT_TYPE(u, 1));
    ASSERT_EQ(8, sizeof(ring_channel_t));
    ASSERT_EQ(12, sizeof(ring_pkt_type_t));
}

TEST(ringlog_ctl)
{
    ASSERT_EQ(0x28, OFF(RINGLOG_$CTL, RINGLOG_$CTL.spinlock));
    ASSERT_EQ(0x2C, OFF(RINGLOG_$CTL, RINGLOG_$CTL.filter_id));
    ASSERT_EQ(0x38, OFF(RINGLOG_$CTL, RINGLOG_$CTL.logging_active));
    ASSERT_EQ((uintptr_t)&RINGLOG_$CTL.wired_pages[0], (uintptr_t)&RINGLOG_WIRED_PAGE(1));
    ASSERT_EQ((uintptr_t)&RINGLOG_$CTL.wired_pages[9], (uintptr_t)&RINGLOG_WIRED_PAGE(10));
    ASSERT_EQ(-1, RINGLOG_$CTL.mbx_sock_filter);
    ASSERT_EQ(-1, RINGLOG_$CTL.who_sock_filter);
    ASSERT_EQ(-1, RINGLOG_$CTL.nil_sock_filter);
    ASSERT_EQ(0, RINGLOG_$CTL.logging_active);
    ASSERT_EQ(-1, RINGLOG_$CTL.first_entry_flag);
    ASSERT_EQ(0, RINGLOG_$CTL.wire_count);
    ASSERT_EQ(0, RINGLOG_$CTL.filter_id);
}

TEST(ringlog_data_zero)
{
    size_t i;

    for (i = 0; i < sizeof(RINGLOG_$DATA.bytes); i++) {
        ASSERT_EQ(0, RINGLOG_$DATA.bytes[i]);
    }
}

int main(void)
{
    printf("RING module data tests\n");
    RUN_TEST(block_addresses_and_sizes);
    RUN_TEST(wired_offsets_and_stride);
    RUN_TEST(wired_initial_contents);
    RUN_TEST(ctl_driver_record);
    RUN_TEST(ctl_clocks_and_procs);
    RUN_TEST(unit_table_bias);
    RUN_TEST(ringlog_ctl);
    RUN_TEST(ringlog_data_zero);
    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed ? 1 : 0;
}
